  "apps/Control Plane/org-core/internal/http/testdata/auth-core-org-core-retention-posture.contract.json|apps/Control Plane/auth-core/src/auth/fixtures/auth-core-org-core-retention-posture.contract.json"
  "apps/Control Plane/org-core/internal/http/testdata/auth-core-org-core-retention-posture.contract.json.sha256|apps/Control Plane/auth-core/src/auth/fixtures/auth-core-org-core-retention-posture.contract.json.sha256"

