  "apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/tests/fixtures/dp-contracts/rerank-v1/ok.golden.json|apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/ok.golden.json"
  "apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/tests/fixtures/dp-contracts/rerank-v1/skipped-zdr.golden.json|apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/skipped-zdr.golden.json"
  "apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/tests/fixtures/dp-contracts/rerank-v1/degraded-timeout.golden.json|apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/degraded-timeout.golden.json"
  "apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/tests/fixtures/dp-contracts/rerank-v1/SHA256SUMS|apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/SHA256SUMS"
  # QB-T14: the web-rerank lab keeps byte-for-byte copies of the rerank-v1 goldens and their pin.
  "apps/Ingestion Plane/Quarry-v2/lab/evals/fixtures/web-rerank/contracts/rerank-v1/ok.golden.json|apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/ok.golden.json"
  "apps/Ingestion Plane/Quarry-v2/lab/evals/fixtures/web-rerank/contracts/rerank-v1/skipped-zdr.golden.json|apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/skipped-zdr.golden.json"
  "apps/Ingestion Plane/Quarry-v2/lab/evals/fixtures/web-rerank/contracts/rerank-v1/degraded-timeout.golden.json|apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/degraded-timeout.golden.json"
  "apps/Ingestion Plane/Quarry-v2/lab/evals/fixtures/web-rerank/contracts/rerank-v1/SHA256SUMS|apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/SHA256SUMS"

  # QB-M: the retrieval engine's copy of that golden and its pin. The web route's contract test reads the
  # copy through the pin (tests/rerank_contract.rs), and scripts/check-usage-contract.sh section 1b checks it.
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/usage-ledger-v2/usage-envelopes.v2.json|apps/Data Plane v2/services/usage-ledger-rs/tests/fixtures/usage-envelopes.v2.json"
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/usage-ledger-v2/usage-envelopes.v2.json.sha256|apps/Data Plane v2/services/usage-ledger-rs/tests/fixtures/usage-envelopes.v2.json.sha256"

  # WS12 S7: the SPA's copy of the SSE payload golden and its pin. scripts/verify-sse-frames.mjs checks a
  # captured transcript against the copy inside the Frontend tree.
  "apps/Frontend Plane/verevonv3/src/shared/api/contracts/sse-event-payloads.json|apps/Model Plane/api/contracts/sse-event-payloads.json"
  "apps/Frontend Plane/verevonv3/src/shared/api/contracts/sse-event-payloads.json.sha256|apps/Model Plane/api/contracts/sse-event-payloads.json.sha256"

  # WS24-S5: the SPA's copy of the admission contract (generated by its own test, which must match the golden).
  "apps/Frontend Plane/verevonv3/src/shared/api/contracts/agent-action-admission.json|apps/Model Plane/api/contracts/agent-action-admission.json"

  # WS24-S5: capability-core's copy (read by the admission table in WS24-S6; vendored now so the digest is pinned).
  "apps/Model Plane/go/services/capability-core/internal/api/testdata/agent-action-admission.json|apps/Model Plane/api/contracts/agent-action-admission.json"

  # WS24-S5: execution-core's copy, read by tests/agent_action_admission_contract.rs.
  "apps/Model Plane/rust/services/execution-core/tests/fixtures/agent-action-admission.json|apps/Model Plane/api/contracts/agent-action-admission.json"

  # WS24-S5: model-gateway's copy, read by the Ask-loop arms test in src/tool_loop.rs.
  "apps/Model Plane/rust/services/model-gateway/tests/fixtures/agent-action-admission.json|apps/Model Plane/api/contracts/agent-action-admission.json"
