# "<repo-relative golden>|<consumer>|<tree its copy must live in>|<owning task>"
# Who must vendor which golden (Z-10). A consumer is satisfied by any VENDORED row for
# the golden whose copy lives under its tree, so the exact fixture directory stays the
# consumer's choice. Until it is satisfied it is reported "pending"; under
# REQUIRE_CONTRACT it fails. A task that vendors a copy appends its VENDORED rows (the
# copy and its .sha256 pin) in the same change.
CONSUMERS=(
  # The posture matrix: each plane evaluates the rows with its own real function.
  "apps/Model Plane/api/contracts/zdr-posture-matrix.json|auth-core|apps/Control Plane/auth-core/|Z-14 (decision function, mint claims)"
  "apps/Model Plane/api/contracts/zdr-posture-matrix.json|mp-contracts|apps/Model Plane/rust/crates/mp-contracts/|Z-11 (resolver)"
  "apps/Model Plane/api/contracts/zdr-posture-matrix.json|model-gateway|apps/Model Plane/rust/services/model-gateway/|Z-15 (normalize and stream entry)"
  "apps/Model Plane/api/contracts/zdr-posture-matrix.json|execution-core|apps/Model Plane/rust/services/execution-core/|WS03 S9 (loop fold ZDR matrix: the shared durable gate opens for persistent only)"
  "apps/Model Plane/api/contracts/zdr-posture-matrix.json|bff-gateway|apps/Frontend Plane/verevonv3/apps/gateway/|Z-03 and Z-19 (org posture, turn retention)"
  "apps/Model Plane/api/contracts/zdr-posture-matrix.json|conversation-core|apps/Application Plane/conversation-core/|Z-03 (org posture reader)"
  "apps/Model Plane/api/contracts/zdr-posture-matrix.json|integration-corev2|apps/Ingestion Plane/integration-corev2/|Z-13 (acknowledgement states; named by design section 9, not by the Z-13 entry)"
  # The capability contract: one source for what a connection can do.
  "apps/Model Plane/api/contracts/connection-zdr-capabilities.json|integration-corev2|apps/Ingestion Plane/integration-corev2/|Z-12 (assessor, go:embed)"
  "apps/Model Plane/api/contracts/connection-zdr-capabilities.json|inference-core|apps/Model Plane/rust/services/inference-core/|Z-10 (cross-check against the real provider capabilities)"
  # Quarry's token-request manifest: Auth Core's contract spec runs the real
  # authorizePlaneServicePrincipal over every row of a byte-for-byte vendored copy
  # (granted rows must be authorized, granted:false rows refused).
  "apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/contracts/cross-plane-token-requests.json|auth-core|apps/Control Plane/auth-core/|CR-T17 (plane-calls manifest contract spec; QB-T02 owns the manifest)"
  # The Data Plane inference client: the wire statuses inference-core emits, and the
  # token answers Auth Core's real mint gives its two background callers.
  "apps/Model Plane/api/contracts/infer-statuses.json|inference-client|apps/Data Plane v2/services/inference-client-rs/|CR-T5 (typed status decoder)"
  "apps/Control Plane/auth-core/src/auth/fixtures/inference-service-tokens.golden.json|inference-client|apps/Data Plane v2/services/inference-client-rs/|CR-T5 (token client and real-policy test)"
  # The contextualizer built on it: the same two contracts, vendored into the embedding engine.
  "apps/Model Plane/api/contracts/infer-statuses.json|embedding-engine|apps/Data Plane v2/services/embedding-engine-rs/|CR-T7 (outcome table over every wire status)"
  "apps/Control Plane/auth-core/src/auth/fixtures/inference-service-tokens.golden.json|embedding-engine|apps/Data Plane v2/services/embedding-engine-rs/|CR-T7 (engine tests replay the real mint)"
  # Z-01: model-gateway refuses a user token whose zdr claim is absent; its tests replay the real user body.
  "apps/Control Plane/auth-core/src/auth/fixtures/quarry-token-claims.golden.json|model-gateway|apps/Model Plane/rust/services/model-gateway/|Z-01 (strict zdr claim, user body of the real mint)"
  # Z-05b: the SPA renders every code of the refusal catalogue in Norwegian and English, with its action.
  "apps/Model Plane/api/contracts/zdr-refusals.json|spa|apps/Frontend Plane/verevonv3/|Z-05b (every code: NO and EN text, action, feature labels)"
  # The Data Plane retrieve-v1 contract: Quarry's vector leg sends the golden request, reads the
  # golden response strictly and maps the golden zdr_mode values (QB-T10).
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/retrieve-v1/request.golden.json|quarry-runtime|apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/|QB-T10 (vector leg request, byte for byte)"
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/retrieve-v1/response.golden.json|quarry-runtime|apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/|QB-T10 (strict response mirror)"
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/retrieve-v1/zdr-modes.golden.json|quarry-runtime|apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/|QB-T10 (typed zdr_mode map)"
  # The Data Plane rerank-v1 answers: Quarry reads each golden strictly (QB-T09).
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/ok.golden.json|quarry-runtime|apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/|QB-T09 (ok answer, scores by index)"
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/skipped-zdr.golden.json|quarry-runtime|apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/|QB-T09 (skip reasons keep the order)"
  "apps/Data Plane v2/services/retrieval-engine-rs/tests/fixtures/contracts/rerank-v1/degraded-timeout.golden.json|quarry-runtime|apps/Ingestion Plane/Quarry-v2/crates/quarry-runtime/|QB-T09 (degraded reasons keep the order)"
  # WS12 S7: the SPA checks every captured SSE frame against the Rust-generated payload golden.
  "apps/Model Plane/api/contracts/sse-event-payloads.json|spa|apps/Frontend Plane/verevonv3/|WS12 S7 (key, type and presence of every ChatEvent payload)"
  # WS24-S5: every consumer that admits or reads an agent action vendors the admission contract.
  "apps/Model Plane/api/contracts/agent-action-admission.json|spa|apps/Frontend Plane/verevonv3/|WS24-S5 (the side map and the registry generate it)"
  "apps/Model Plane/api/contracts/agent-action-admission.json|execution-core|apps/Model Plane/rust/services/execution-core/|WS24-S5 (every admitted id has an owner path in the Do catalogue)"
  "apps/Model Plane/api/contracts/agent-action-admission.json|model-gateway|apps/Model Plane/rust/services/model-gateway/|WS24-S5 (every Ask-loop read arm is a contract row, and the reverse)"
  "apps/Model Plane/api/contracts/agent-action-admission.json|capability-core|apps/Model Plane/go/services/capability-core/|WS24-S5 (vendored; the admission table reads it in WS24-S6)"
)

passes=0
failures=0
pass() { printf 'ok - %s\n' "$1"; passes=$((passes + 1)); }
fail() { printf 'not ok - %s\n' "$1" >&2; failures=$((failures + 1)); }

sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | cut -d' ' -f1
  else
    shasum -a 256 "$1" | cut -d' ' -f1
  fi
}

has_carriage_return() { [[ -n "$(tr -d '\n' <"$1" | tr -cd '\r')" ]]; }

check_goldens() {
  local row path pinned actual sibling
  for row in "${GOLDENS[@]}"; do
    path="${row%%|*}"
    pinned="${row##*|}"
    if [[ ! -f "$ROOT/$path" ]]; then
      fail "golden is missing: $path"
      continue
    fi
    if has_carriage_return "$ROOT/$path"; then
      fail "golden has CR line endings (it is hashed byte for byte, LF only): $path"
      continue
    fi
    actual="$(sha256_of "$ROOT/$path")"
    if [[ "$actual" == "$pinned" ]]; then
      pass "golden matches its pinned digest: $path"
      # A pin file beside the golden, if there is one, is what its vendored copies
      # carry; it must say the same as the digest pinned here.
      if [[ -f "$ROOT/$path.sha256" ]]; then
        sibling=""
        read -r sibling _ <"$ROOT/$path.sha256" || true
        if [[ "$sibling" == "$pinned" ]]; then
          pass "pin file beside the golden agrees: $path.sha256"
        else
          fail "pin file beside the golden disagrees with the pinned digest: $path.sha256 says '$sibling', expected $pinned"
        fi
      fi
    else
      fail "golden differs from its pinned digest: $path
    pinned   $pinned
    actual   $actual
    If the change is intended, regenerate it with its owner's generator and update the pin in $(basename "$SELF")."
    fi
  done
}

check_vendored() {
  local row copy golden
  for row in "${VENDORED[@]}"; do
    copy="${row%%|*}"
    golden="${row##*|}"
    if [[ ! -f "$ROOT/$copy" ]]; then
      fail "vendored copy is missing: $copy"
    elif [[ ! -f "$ROOT/$golden" ]]; then
      fail "the golden a copy vendors is missing: $golden (copy: $copy)"
    elif cmp -s "$ROOT/$copy" "$ROOT/$golden"; then
      pass "vendored copy is byte-identical to its golden: $copy"
    else
      fail "vendored copy differs from its golden: $copy (golden: $golden)"
    fi
  done
}

# Node on Windows cannot read a Cygwin path; everywhere else this is the identity.
to_native() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -w "$1"; else printf '%s' "$1"; fi
}

# The ZDR goldens are authored specifications, so a matching digest is not enough: the
# strict loader (scripts/tests/zdr-contract-schema.mjs) must accept them too. When the
# refusal catalogue golden (Z-05a, zdr-refusals.json) is listed in GOLDENS, every
# refusal code of the matrix must exist in it.
check_schema() {
  local out row path
  local args=()
  if ! command -v node >/dev/null 2>&1; then
    fail "node is required to check the ZDR contract goldens (scripts/tests/zdr-contract-schema.mjs); a check that cannot run is a failure"
    return 0
  fi
  for row in "${GOLDENS[@]}"; do
    path="${row%%|*}"
    if [[ "$path" == "apps/Model Plane/api/contracts/zdr-refusals.json" ]]; then
      args=(--refusals "$path")
    fi
  done
  # The loader reads the refusal catalogue at import time. Point it at the catalogue of the tree
  # being checked: the self-test runs this function from a scratch copy of the script, and a path
  # relative to the script's own location would then leave the scratch tree.
  if out="$(ZDR_REFUSALS_CATALOGUE="$(to_native "$ROOT/apps/Model Plane/api/contracts/zdr-refusals.json")" node "$(to_native "$SCRIPT_DIR/zdr-contract-schema.mjs")" "$(to_native "$ROOT")" ${args[@]+"${args[@]}"} 2>&1)"; then
    pass "ZDR contract goldens load strictly and agree with each other (zdr-contract-schema.mjs)"
  else
    fail "ZDR contract goldens are malformed or inconsistent (zdr-contract-schema.mjs):
$out"
  fi
}

# Every consumer in CONSUMERS must have vendored its copy. Pending is reported;
# under REQUIRE_CONTRACT it is a failure (and the function returns non-zero).
check_consumers() {
  local row golden consumer prefix task vendored copy vgolden satisfied
  local pending=0
  for row in "${CONSUMERS[@]}"; do
    IFS='|' read -r golden consumer prefix task <<<"$row"
    satisfied=0
    for vendored in "${VENDORED[@]}"; do
      IFS='|' read -r copy vgolden _ <<<"$vendored"
      if [[ "$vgolden" == "$golden" && "$copy" == "$prefix"* ]]; then
        satisfied=1
        break
      fi
    done
    if ((satisfied)); then
      pass "$consumer vendors $(basename "$golden") [$task]"
    elif [[ -n "${REQUIRE_CONTRACT:-}" ]]; then
      fail "REQUIRE_CONTRACT is set but $consumer has not vendored $golden into $prefix [$task]"
      pending=$((pending + 1))
    else
      printf 'pending - %s has not vendored %s into %s yet [%s]\n' "$consumer" "$(basename "$golden")" "$prefix" "$task"
      pending=$((pending + 1))
    fi
  done
  if [[ -n "${REQUIRE_CONTRACT:-}" ]]; then
    ((pending == 0))
  fi
}

# The check is only worth having if it can fail. Copy the goldens into a scratch
# tree, flip one byte, and require the same checks to reject it; then require
# them to accept the untouched copy.
self_test() {
  local row path pin matrix malformed
  SCRATCH="$(mktemp -d)"
  trap 'rm -rf "$SCRATCH"' EXIT
  for row in "${GOLDENS[@]}"; do
    path="${row%%|*}"
    mkdir -p "$SCRATCH/$(dirname "$path")"
    cp "$ROOT/$path" "$SCRATCH/$path"
    # The pin file beside a golden, if there is one, is checked too.
    if [[ -f "$ROOT/$path.sha256" ]]; then
      cp "$ROOT/$path.sha256" "$SCRATCH/$path.sha256"
    fi
  done
  for row in "${VENDORED[@]}"; do
    # Both sides: the copy, and the golden (or pin) it vendors, which is not
    # always one of GOLDENS.
    for path in "${row%%|*}" "${row##*|}"; do
      mkdir -p "$SCRATCH/$(dirname "$path")"
      cp "$ROOT/$path" "$SCRATCH/$path"
    done
  done
  # REQUIRE_CONTRACT is emptied here: this run asks only whether an untouched copy passes.
  if ! REQUIRE_CONTRACT= CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SELF" >/dev/null 2>&1; then
    echo "self-test: the checks reject an untouched copy of the goldens" >&2
    return 1
  fi
  path="${GOLDENS[0]%%|*}"
  printf ' ' >>"$SCRATCH/$path"
  if CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SELF" >/dev/null 2>&1; then
    echo "self-test: the checks accept a tampered golden" >&2
    return 1
  fi
  # A vendored copy that drifted from its golden must fail too, with the golden itself intact.
  cp "$ROOT/$path" "$SCRATCH/$path"
  if ((${#VENDORED[@]} > 0)); then
    path="${VENDORED[0]%%|*}"
    printf ' ' >>"$SCRATCH/$path"
    if CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SELF" >/dev/null 2>&1; then
      echo "self-test: the checks accept a vendored copy that differs from its golden" >&2
      return 1
    fi
    # Put the copy back: every check below must fail for ITS reason, not because this one is still drifted.
    cp "$ROOT/$path" "$SCRATCH/$path"
  fi
  if ! REQUIRE_CONTRACT= CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SELF" >/dev/null 2>&1; then
    echo "self-test: the scratch copy does not pass again after the tamper checks, so the checks below would prove nothing" >&2
    return 1
  fi

  # The strict loader must reject a malformed ZDR golden on its own. A digest pin only
  # proves the file did not change; it says nothing about whether the file is well formed,
  # so this runs the loader directly, with no pin in the way.
  if ! command -v node >/dev/null 2>&1; then
    echo "self-test: node is required (scripts/tests/zdr-contract-schema.mjs)" >&2
    return 1
  fi
  matrix="apps/Model Plane/api/contracts/zdr-posture-matrix.json"
  node -e 'const fs=require("fs");const p=process.argv[1];const d=JSON.parse(fs.readFileSync(p,"utf8"));delete d.decision_rows[0].expect.code;fs.writeFileSync(p,JSON.stringify(d,null,2)+"\n")' "$(to_native "$SCRATCH/$matrix")"
  if node "$(to_native "$SCRIPT_DIR/zdr-contract-schema.mjs")" "$(to_native "$SCRATCH")" >/dev/null 2>&1; then
    echo "self-test: the strict loader accepts a posture matrix row without a code" >&2
    return 1
  fi
  node -e 'const fs=require("fs");const p=process.argv[1];const d=JSON.parse(fs.readFileSync(p,"utf8"));d.surprise=true;fs.writeFileSync(p,JSON.stringify(d,null,2)+"\n")' "$(to_native "$SCRATCH/$matrix")"
  if node "$(to_native "$SCRIPT_DIR/zdr-contract-schema.mjs")" "$(to_native "$SCRATCH")" >/dev/null 2>&1; then
    echo "self-test: the strict loader accepts a posture matrix with an unknown field" >&2
    return 1
  fi
  cp "$ROOT/$matrix" "$SCRATCH/$matrix"

  # End to end: a malformed golden whose pins were all updated to match must still fail the
  # whole check. Run a copy of this script whose pinned digest is the malformed file's own.
  pin="$matrix.sha256"
  node -e 'const fs=require("fs");const p=process.argv[1];const d=JSON.parse(fs.readFileSync(p,"utf8"));delete d.decision_rows[0].expect.code;fs.writeFileSync(p,JSON.stringify(d,null,2)+"\n")' "$(to_native "$SCRATCH/$matrix")"
  malformed="$(sha256_of "$SCRATCH/$matrix")"
  printf '%s  zdr-posture-matrix.json\n' "$malformed" >"$SCRATCH/$pin"
  for row in "${GOLDENS[@]}"; do
    if [[ "${row%%|*}" == "$matrix" ]]; then
      sed "s/${row##*|}/$malformed/" "$SELF" >"$SCRATCH/repinned-self.sh"
    fi
  done
  cp "$SCRIPT_DIR/zdr-contract-schema.mjs" "$SCRATCH/zdr-contract-schema.mjs"
  if ! grep -q "$malformed" "$SCRATCH/repinned-self.sh"; then
    echo "self-test: could not re-pin the scratch copy of this script" >&2
    return 1
  fi
  if REQUIRE_CONTRACT= CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SCRATCH/repinned-self.sh" >/dev/null 2>&1; then
    echo "self-test: a malformed ZDR golden with a matching digest and pin passes the whole check" >&2
    return 1
  fi
  cp "$ROOT/$matrix" "$SCRATCH/$matrix"
  cp "$ROOT/$pin" "$SCRATCH/$pin"

  # A pin file beside a golden that disagrees with the pinned digest must fail.
  printf '%064d  zdr-posture-matrix.json\n' 0 >"$SCRATCH/$pin"
  if CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SELF" >/dev/null 2>&1; then
    echo "self-test: the checks accept a pin file that disagrees with the pinned digest" >&2
    return 1
  fi
  cp "$ROOT/$pin" "$SCRATCH/$pin"

  # A consumer that has not vendored must fail under REQUIRE_CONTRACT, be reported
  # (not failed) without it, and pass once a copy lives in its tree.
  if (CONSUMERS=("apps/none/golden.json|ghost|apps/ghost/|Z-00"); VENDORED=(); REQUIRE_CONTRACT=1; check_consumers) >/dev/null 2>&1; then
    echo "self-test: a pending consumer passes under REQUIRE_CONTRACT" >&2
    return 1
  fi
  if ! (CONSUMERS=("apps/none/golden.json|ghost|apps/ghost/|Z-00"); VENDORED=(); REQUIRE_CONTRACT=; check_consumers) >/dev/null 2>&1; then
    echo "self-test: a pending consumer fails without REQUIRE_CONTRACT" >&2
    return 1
  fi
  if ! (CONSUMERS=("apps/none/golden.json|ghost|apps/ghost/|Z-00"); VENDORED=("apps/ghost/tests/golden.json|apps/none/golden.json"); REQUIRE_CONTRACT=1; check_consumers) >/dev/null 2>&1; then
    echo "self-test: a consumer with a vendored copy in its tree is still pending" >&2
    return 1
  fi
  if (CONSUMERS=("apps/none/golden.json|ghost|apps/ghost/|Z-00"); VENDORED=("apps/elsewhere/golden.json|apps/none/golden.json" "apps/ghost/tests/other.json|apps/none/other.json"); REQUIRE_CONTRACT=1; check_consumers) >/dev/null 2>&1; then
    echo "self-test: a copy in another tree, or a copy of another golden, satisfies a consumer" >&2
    return 1
  fi
  # The same, through the whole script: a copy of it with one consumer nobody satisfies must
  # exit non-zero under REQUIRE_CONTRACT and zero without it.
  awk '{print} /^CONSUMERS=\($/ {print "  \"apps/none/golden.json|ghost|apps/ghost/|Z-00\""}' "$SELF" >"$SCRATCH/ghost-self.sh"
  cp "$SCRIPT_DIR/zdr-contract-schema.mjs" "$SCRATCH/zdr-contract-schema.mjs"
  if ! grep -q 'ghost|apps/ghost/' "$SCRATCH/ghost-self.sh"; then
    echo "self-test: could not add a ghost consumer to the scratch copy of this script" >&2
    return 1
  fi
  if ! REQUIRE_CONTRACT= CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SCRATCH/ghost-self.sh" >/dev/null 2>&1; then
    echo "self-test: a pending consumer fails the whole check without REQUIRE_CONTRACT" >&2
    return 1
  fi
  if REQUIRE_CONTRACT=1 CONTRACT_SYNC_ROOT="$SCRATCH" bash "$SCRATCH/ghost-self.sh" >/dev/null 2>&1; then
    echo "self-test: a pending consumer does not fail the whole check under REQUIRE_CONTRACT" >&2
    return 1
  fi
  echo "self-test ok: an untouched copy passes, a tampered golden fails, a drifted vendored copy fails, a malformed ZDR golden fails, a disagreeing pin fails, a pending consumer fails under REQUIRE_CONTRACT"
}

if [[ "${1:-}" == "--self-test" ]]; then
  self_test
  exit $?
fi

check_goldens
check_vendored
check_schema
check_consumers || true
printf '%s passed, %s failed\n' "$passes" "$failures"
[[ "$failures" -eq 0 ]]
